export default function Portfolio() {
  const [active, setActive] = useState("home");
  const [phase, setPhase] = useState("idle"); // idle | opening
  const [split, setSplit] = useState(0);
  const [revealed, setRevealed] = useState(false);
  const [donutSize, setDonutSize] = useState(320);
  const sectionRefs = useRef({});
  const heroWrapperRef = useRef(null);
  const phaseRef = useRef("idle");

  useEffect(() => {
    phaseRef.current = phase;
  }, [phase]);

  // full donut fills the first screen — size it to the viewport, capped for perf
  useEffect(() => {
    const computeSize = () => {
      const s = Math.min(window.innerWidth, window.innerHeight);
      setDonutSize(Math.max(s, 280));
    };
    computeSize();
    window.addEventListener("resize", computeSize);
    return () => window.removeEventListener("resize", computeSize);
  }, []);

  const openDonut = () => {
    if (phaseRef.current !== "idle") return;
    setSplit(1);
    setPhase("opening");
  };

  // the big moment — the donut splits open (eased inside the 3D loop) and cream
  // floods out. As it drains away the About page is revealed underneath, growing
  // out of the donut's hole while cream still drips over it. No scrolling.
  useEffect(() => {
    if (phase !== "opening") return;
    const closeT = window.setTimeout(() => setSplit(0), 3400);
    const revealT = window.setTimeout(() => {
      setRevealed(true);
      setActive("about");
    }, 2400);
    const endT = window.setTimeout(() => setPhase("idle"), 4600);
    return () => {
      window.clearTimeout(closeT);
      window.clearTimeout(revealT);
      window.clearTimeout(endT);
    };
  }, [phase]);

  // scroll-spy for the nav (re-observes once the About panel is revealed)
  useEffect(() => {
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) setActive(entry.target.id);
        });
      },
      { rootMargin: "-45% 0px -45% 0px", threshold: 0 }
    );
    Object.values(sectionRefs.current).forEach((el) => el && obs.observe(el));
    return () => obs.disconnect();
  }, [revealed]);

  const registerSection = (id) => (el) => {
    sectionRefs.current[id] = el;
  };

  const scrollTo = (id) => {
    const el = sectionRefs.current[id];
    if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  return (
    <div className="portfolio-root">
      <style>{CSS}</style>

      <NavBar active={active} onNavigate={scrollTo} />

      <main>
        <div
          id="home"
          ref={(el) => {
            heroWrapperRef.current = el;
            registerSection("home")(el);
          }}
          className="hero-wrapper"
          style={{ height: revealed ? "auto" : "100vh" }}
        >
          {revealed ? (
            <section id="about" ref={registerSection("about")} className="about about-revealed">
              <div className="about-decor" aria-hidden="true">
                <DonutBadge icing="#E8A93B" size={54} className="decor-donut ad-1" />
                <DonutBadge icing="#8FE3C4" size={40} className="decor-donut ad-2" />
                <HalfDonut icing="#FF8FAB" size={34} className="ad-3" />
                <HalfDonut icing="#845EC2" size={28} className="ad-4" flip />
                {DECOR_SPRINKLES.map((s, i) => (
                  <span key={i} className={`decor-sprinkle spr-${i % 4}`} style={s} />
                ))}
              </div>
              <div className="section-head">
                <span className="section-kicker">about me</span>
                <h2 className="section-title">What's in the box</h2>
              </div>
              <div className="about-receipt">
                <div className="receipt-icing" aria-hidden="true">
                  <div className="receipt-icing-drips">
                    {CARD_DRIPS.map((h, i) => (
                      <span key={i} style={{ height: h }} />
                    ))}
                  </div>
                </div>
                <div className="receipt-inner">
                  <div className="receipt-head">
                    <DonutBadge icing="#FF8FAB" size={34} className="receipt-donut" />
                    <div className="receipt-shop">
                      <span className="receipt-shop-name">DONUTS &amp; DEVOPS</span>
                      <span className="receipt-shop-tag">est. 2005 · baked fresh daily</span>
                    </div>
                    <span className="receipt-stamp">ORDER #001</span>
                  </div>
                  <hr className="receipt-perf" />
                  <div className="receipt-body">
                    <div className="receipt-photo-col">
                      <div className="receipt-photo-frame">
                        <img src={PROFILE_IMG} alt="Amrit Kang" className="receipt-photo" />
                        <span className="frame-sprinkle fs-1" />
                        <span className="frame-sprinkle fs-2" />
                        <span className="frame-sprinkle fs-3" />
                        <span className="frame-sprinkle fs-4" />
                        <div className="frame-icing" aria-hidden="true">
                          <span className="frame-drip fd-1" />
                          <span className="frame-drip fd-2" />
                          <span className="frame-drip fd-3" />
                          <span className="frame-drip fd-4" />
                        </div>
                      </div>
                      <div className="receipt-id">
                        <span className="receipt-id-name">AMRIT KANG</span>
                        <span className="receipt-id-tag">full-stack dev · part-time pastry chef</span>
                        <span className="receipt-id-line">ID #001 · BITS PILANI · 2ND YEAR</span>
                      </div>
                    </div>
                    <div className="receipt-info-col">
                      <ul className="receipt-bullets">
                        <li>Second-year <strong>CS</strong> student at <strong>BITS Pilani</strong></li>
                        <li>Baking <strong>full-stack apps</strong>, <strong>AI products</strong> and backend systems</li>
                        <li>Solving real problems people actually have</li>
                        <li>Shipping fast and learning in public</li>
                        <li>Sprinkling time between <strong>Swift</strong>, <strong>Python</strong> and <strong>System Design</strong></li>
                        <li>Open to internships, freelance work and interesting people</li>
                      </ul>
                      <div className="receipt-facts">
                        {FACTS.map((f) => (
                          <div key={f.label} className="receipt-line">
                            <span className="receipt-line-label">{f.label}</span>
                            <span className="receipt-line-dots" aria-hidden="true" />
                            <span className="receipt-line-value">{f.value}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                  <hr className="receipt-perf" />
                  <div className="receipt-total">
                    <span>TOTAL</span>
                    <span>one big donut</span>
                  </div>
                  <div className="receipt-barcode" aria-hidden="true" />
                  <p className="receipt-thanks">thanks for stopping by — the dough is on me</p>
                </div>
              </div>
            </section>
          ) : (
            <section className="hero">
              <div className="hero-sprinkle-field" aria-hidden="true">
                {Array.from({ length: 14 }).map((_, i) => (
                  <span key={i} className={`floating-dot dot-${i % 6}`} style={{
                    left: `${(i * 7.3) % 100}%`,
                    animationDelay: `${(i * 0.6) % 5}s`,
                    animationDuration: `${6 + (i % 5)}s`,
                  }} />
                ))}
              </div>

              <Donut3D
                size={donutSize}
                className="hero-donut"
                split={split}
                onClick={openDonut}
              />
            </section>
          )}
        </div>

        <section id="projects" ref={registerSection("projects")} className="projects">
          <div className="projects-decor" aria-hidden="true">
            <DonutBadge icing="#FF8FAB" size={72} className="decor-donut dd-1" />
            <DonutBadge icing="#8FE3C4" size={46} className="decor-donut dd-2" />
            <DonutBadge icing="#E8A93B" size={58} className="decor-donut dd-3" />
            {DECOR_SPRINKLES.map((s, i) => (
              <span key={i} className={`decor-sprinkle spr-${i % 4}`} style={s} />
            ))}
          </div>
          <div className="section-head">
            <span className="section-kicker">projects</span>
            <h2 className="section-title">Some masterpieces I've baked</h2>
            <p className="section-desc">
              A batch of full-stack and AI projects, pulled straight from{" "}
              <a href="https://github.com/amritkang165" target="_blank" rel="noopener noreferrer">
                github.com/amritkang165
              </a>
              . Open the book — every page is a project, and your order slips onto the receipt.
            </p>
          </div>
          <MenuBook projects={PROJECTS} />
        </section>

        <section id="contact" ref={registerSection("contact")} className="contact">
          <DonutBadge size={64} />
          <h2 className="contact-title">Let's build something.</h2>
          <p className="contact-sub">
            Open to internships, freelance work, and collaborations — reach out any time.
          </p>
          <div className="contact-links">
            <a className="btn btn-primary" href="mailto:amritkang2805@icloud.com">
              <Mail size={16} /> Email me
            </a>
            <a
              className="btn btn-ghost"
              href="https://github.com/amritkang165"
              target="_blank"
              rel="noopener noreferrer"
            >
              <Github size={16} /> GitHub
            </a>
            <a
              className="btn btn-ghost"
              href="https://www.linkedin.com/in/amritkang28"
              target="_blank"
              rel="noopener noreferrer"
            >
              <Linkedin size={16} /> LinkedIn
            </a>
          </div>
          <p className="footer-tagline">Build. Break. Learn. Repeat.</p>
        </section>
      </main>

      {phase !== "idle" && (
        <div className="cream-stage" aria-hidden="true">
          <div className="cream-flood">
            <div className="cream-blob" />
            {CREAM_FLIES.map((s, i) => (
              <span key={i} className="cream-fly" style={s} />
            ))}
          </div>
          {CREAM_DRIPS.map((d, i) => (
            <span key={i} className="cream-drip" style={d} />
          ))}
          {CREAM_RIVULETS.map((d, i) => (
            <span key={i} className="cream-rivulet" style={d} />
          ))}
        </div>
      )}

      <SyrupTrail />
    </div>
  );
}

